from __future__ import annotations

from dataclasses import dataclass
from threading import RLock
from time import time


@dataclass
class SessionEntry:
    user_id: str
    state: dict
    last_response: dict
    updated_at: float


class SkinSessionStore:
    """Skin Tracking 專用的開發期 session store；publish 時可換成 Redis adapter。"""

    def __init__(self, ttl_seconds: int = 3600):
        self.ttl_seconds = ttl_seconds
        # session_id can be generated by a browser, so user_id is part of the key.
        self._items: dict[tuple[str, str], SessionEntry] = {}
        self._lock = RLock()

    def get(self, session_id: str, user_id: str) -> SessionEntry | None:
        key = (user_id, session_id)
        with self._lock:
            entry = self._items.get(key)
            if not entry:
                return None
            if time() - entry.updated_at > self.ttl_seconds:
                self._items.pop(key, None)
                return None
            return entry

    def put(self, session_id: str, user_id: str, state: dict, last_response: dict) -> None:
        with self._lock:
            self._items[(user_id, session_id)] = SessionEntry(
                user_id,
                state,
                last_response,
                time(),
            )

    def delete(self, session_id: str, user_id: str) -> None:
        with self._lock:
            self._items.pop((user_id, session_id), None)
